 crates/core/src/pipeline/rdt.rs            |  12 ++-
 crates/core/src/types/output.rs            |  21 ++--
 crates/core/src/types/output/tests.rs      |  17 +++-
 docs/architecture/serialization-formats.md |  29 ++----
 6 files changed, 191 insertions(+), 46 deletions(-)
            )
