    /// member is an enum only when Storybook could not read it from its type name (see
    /// [`PropType::splits_into_json_options`]), because the enum shape turns `true` into the string "true". A union
    /// with no members, or with only booleans, has nothing to offer.
    pub fn is_literal_union(&self) -> bool {
        let is_option = |m: &PropType| matches!(m, PropType::StringLiteral(_) | PropType::NumberLiteral(_));
        match self {
            PropType::Union(members) => {
                let is_literal = |m: &PropType| is_option(m) || matches!(m, PropType::BoolLiteral(_));
                members.iter().any(is_option) && members.iter().all(is_literal) && !self.splits_into_json_options()
            }
